/**
 * Writers for MP3 and ADTS fixtures, generated by code. MP3 frames are
 * silent Layer III frames (zeroed side information, so every granule
 * decodes to silence), and ADTS frames carry a silent AAC-LC stereo block.
 * Options produce the tags, prefixes and crafted frames the walkers must
 * handle.
 */

const MP3_RATES: Record<string, Record<number, number>> = {
  "1": { 44100: 0, 48000: 1, 32000: 2 },
  "2": { 22050: 0, 24000: 1, 16000: 2 },
  "2.5": { 11025: 0, 12000: 1, 8000: 2 },
};

export interface Mp3FrameOptions {
  readonly version?: 1 | 2 | 2.5;
  readonly sampleRate?: number;
  readonly mono?: boolean;
  /** Bitrate index 1–14; 9 is 128 kbit/s for MPEG-1 layer III. */
  readonly bitrateIndex?: number;
}

function frameLength(options: Mp3FrameOptions): number {
  const version = options.version ?? 1;
  const rate = options.sampleRate ?? 44_100;
  const index = options.bitrateIndex ?? 9;
  const kbps =
    version === 1
      ? [0, 32, 40, 48, 56, 64, 80, 96, 112, 128, 160, 192, 224, 256, 320][index]
      : [0, 8, 16, 24, 32, 40, 48, 56, 64, 80, 96, 112, 128, 144, 160][index];
  return Math.floor(((version === 1 ? 144 : 72) * (kbps ?? 0) * 1_000) / rate);
}

/** One silent layer III frame, optionally carrying bytes after its header, such as a tag. */
export function mp3Frame(options: Mp3FrameOptions = {}, payload: number[] = []): number[] {
  const version = options.version ?? 1;
  const rate = options.sampleRate ?? 44_100;
  const versionBits = version === 1 ? 3 : version === 2 ? 2 : 0;
  const rateIndex = MP3_RATES[String(version)]?.[rate];
  if (rateIndex === undefined) throw new Error(`no rate ${rate} for MPEG-${version}`);
  const header = [
    0xff,
    0xe0 | (versionBits << 3) | (1 << 1) | 1, // layer III, no CRC
    ((options.bitrateIndex ?? 9) << 4) | (rateIndex << 2),
    options.mono ? 0xc0 : 0x00,
  ];
  const frame = new Array<number>(frameLength(options)).fill(0);
  frame.splice(0, 4, ...header);
  frame.splice(4, payload.length, ...payload);
  return frame.slice(0, frameLength(options));
}

export interface Mp3Options extends Mp3FrameOptions {
  readonly frames: number;
  /** An ID3v2 tag before the first frame. */
  readonly id3?: boolean;
  /** An Info tag in a first frame of its own, with this frame count, and LAME's delay and padding. */
  readonly info?: { readonly frames: number; readonly delay?: number; readonly padding?: number };
  /** A VBRI tag in a first frame of its own. */
  readonly vbri?: { readonly frames: number; readonly delay: number };
  /** Extra frames, already encoded, after the audio. */
  readonly appended?: readonly number[][];
}

function u32(value: number): number[] {
  return [(value >>> 24) & 0xff, (value >>> 16) & 0xff, (value >>> 8) & 0xff, value & 0xff];
}

/** An MP3 file of silent frames. */
export function mp3File(options: Mp3Options): Uint8Array<ArrayBuffer> {
  const bytes: number[] = [];
  if (options.id3) bytes.push(0x49, 0x44, 0x33, 4, 0, 0, 0, 0, 0, 20, ...new Array(20).fill(0));
  const sideInfo = (options.version ?? 1) === 1 ? (options.mono ? 17 : 32) : options.mono ? 9 : 17;
  if (options.info) {
    const { frames, delay = 0, padding = 0 } = options.info;
    const lame = [...[0x4c, 0x41, 0x4d, 0x45], ...new Array(17).fill(0)]; // "LAME" + version etc.
    lame.push((delay >> 4) & 0xff, ((delay & 0xf) << 4) | ((padding >> 8) & 0xf), padding & 0xff);
    const info = [0x49, 0x6e, 0x66, 0x6f, ...u32(0x1), ...u32(frames), ...lame];
    bytes.push(...mp3Frame(options, [...new Array(sideInfo).fill(0), ...info]));
  }
  if (options.vbri) {
    const vbri = [
      ...new Array(32).fill(0),
      0x56,
      0x42,
      0x52,
      0x49,
      0,
      1,
      (options.vbri.delay >> 8) & 0xff,
      options.vbri.delay & 0xff,
      0,
      75,
      ...u32(0),
      ...u32(options.vbri.frames),
    ];
    bytes.push(...mp3Frame(options, vbri));
  }
  for (let i = 0; i < options.frames; i += 1) bytes.push(...mp3Frame(options));
  for (const frame of options.appended ?? []) bytes.push(...frame);
  return Uint8Array.from(bytes);
}

const ADTS_RATES = [
  96_000, 88_200, 64_000, 48_000, 44_100, 32_000, 24_000, 22_050, 16_000, 12_000, 11_025, 8_000,
  7_350,
];

/** A silent AAC-LC raw data block with one channel pair element. */
const SILENT_STEREO_BLOCK = [0x21, 0x00, 0x49, 0x90, 0x02, 0x19, 0x00, 0x23, 0x80];

export interface AdtsFrameOptions {
  readonly sampleRate?: number;
  /** The header's channel configuration; the payload is always a stereo block. */
  readonly channelConfiguration?: number;
}

/** One ADTS frame with a silent AAC-LC block. */
export function adtsFrame(options: AdtsFrameOptions = {}): number[] {
  const rateIndex = ADTS_RATES.indexOf(options.sampleRate ?? 44_100);
  if (rateIndex < 0) throw new Error("no such ADTS rate");
  const configuration = options.channelConfiguration ?? 2;
  const length = 7 + SILENT_STEREO_BLOCK.length;
  return [
    0xff,
    0xf1, // MPEG-4, layer 0, no CRC
    (1 << 6) | (rateIndex << 2) | (configuration >> 2), // AAC LC
    ((configuration & 0x3) << 6) | (length >> 11),
    (length >> 3) & 0xff,
    ((length & 0x7) << 5) | 0x1f,
    0xfc, // buffer fullness, one raw data block
    ...SILENT_STEREO_BLOCK,
  ];
}

/** An ADTS file of silent frames. */
export function adtsFile(
  frames: number,
  options: AdtsFrameOptions & { readonly appended?: readonly number[][] } = {},
): Uint8Array<ArrayBuffer> {
  const bytes: number[] = [];
  for (let i = 0; i < frames; i += 1) bytes.push(...adtsFrame(options));
  for (const frame of options.appended ?? []) bytes.push(...frame);
  return Uint8Array.from(bytes);
}
